 const legacy=[];if(has('hat'))legacy.push('<path d="M59 42h42l-5-18H64Z" fill="#cc5260" stroke="#27384d" stroke-width="3"/><path d="M50 44h60" stroke="#f4ca5a" stroke-width="6" stroke-linecap="round"/>');if(has('crown'))legacy.push('<path d="m61 48 3-17 12 11 8-17 8 17 12-11 3 17Z" fill="#f2c656" stroke="#443950" stroke-width="3"/>');if(has('shades'))legacy.push('<path d="M54 76h22m8 0h22" stroke="#27384d" stroke-width="5"/><rect x="56" y="70" width="19" height="14" rx="5" fill="#244565" stroke="#27384d" stroke-width="3"/><rect x="85" y="70" width="19" height="14" rx="5" fill="#244565" stroke="#27384d" stroke-width="3"/>');if(has('bow'))legacy.push('<path d="M103 54q16-13 13 1t-13 1q-16 12-14-1t14-1Z" fill="#ef80ab" stroke="#34405a" stroke-width="2"/>');if(has('star'))legacy.push('<path d="m112 74 3 7 7 1-5 5 1 7-6-4-6 4 1-7-5-5 7-1Z" fill="#ffe078" stroke="#29394e" stroke-width="2"/>');
 const wings=has('wings')?'<path d="M47 105Q13 76 19 111q5 18 26 25m68-31q34-29 28 6-5 18-26 25" fill="#b4eaf0" stroke="#26384d" stroke-width="3"/>':'';
 const ringed=has('ringed')||has('stardust')?'<ellipse cx="80" cy="137" rx="49" ry="10" fill="none" stroke="#edca69" stroke-width="4" transform="rotate(-11 80 137)"/>':'';
 const descr=`Space courier, ${style} hair, ${head==='none'?'no headgear':head+' headgear'}, ${suitStyle} suit`;
 return `<svg viewBox="0 0 160 170" role="img" aria-label="${descr}" class="creature" xmlns="http://www.w3.org/2000/svg"><title>${descr}</title><circle cx="80" cy="84" r="73" fill="#183a60"/><path d="M29 119Q20 80 39 57L52 64Q80 48 108 64L121 57Q140 81 131 119" fill="${coat}" stroke="#25364c" stroke-width="5" stroke-linejoin="round"/>${wings}<ellipse cx="80" cy="82" rx="34" ry="36" fill="${skin}" stroke="#26384d" stroke-width="3"/>${hairShape}<ellipse cx="66" cy="82" rx="7" ry="10" fill="#fffdf1"/><ellipse cx="94" cy="82" rx="7" ry="10" fill="#fffdf1"/><ellipse cx="68" cy="84" rx="3.2" ry="5.4" fill="#172a3e"/><ellipse cx="96" cy="84" rx="3.2" ry="5.4" fill="#172a3e"/><circle cx="69" cy="82" r="1.4" fill="#fff"/><circle cx="97" cy="82" r="1.4" fill="#fff"/><path d="M72 99q8 8 16 0" fill="none" stroke="#a74c5a" stroke-width="3" stroke-linecap="round"/><circle cx="55" cy="96" r="5" fill="#ed8e83" opacity=".55"/><circle cx="105" cy="96" r="5" fill="#ed8e83" opacity=".55"/><path d="M47 118Q80 108 113 118L122 148Q80 166 38 148Z" fill="${coat}" stroke="#26384d" stroke-width="4" stroke-linejoin="round"/>${stripe}${stars}${belt}<path d="M68 116 80 132 92 116" fill="#f7d36b" stroke="#39445a" stroke-width="2"/><path d="M53 144q27 10 54 0" fill="none" stroke="#ffffff" stroke-opacity=".55" stroke-width="3" stroke-linecap="round"/>${legacy.join('')}${ringed}${antennae}${starclip}${helmet}</svg>`;
