function dwarfSvg(u={}){return courierSvg(u)}
let courierDraft=null;
function courier(){
 const u=state.user||{name:'Visitor',avatar:'#ff2bd6',...CONFIG.look.defaults};courierDraft={...u};
 const gearFor=kinds=>CONFIG.cosmetics.filter(c=>kinds.includes(c.kind)).map(c=>{const own=state.accessories.owned.includes(c.id),eq=c.kind==='hairStyle'?u.hairStyle===c.value:c.kind==='headgear'?u.headgear===c.value:c.kind==='suitStyle'?u.suitStyle===c.value:state.accessories.equipped.includes(c.id);return `<article class="cosmetic"><span class="cosmetic-icon" aria-hidden="true">${c.emoji}</span><div><b>${esc(c.name)}</b><small>${c.cost?`${c.cost} Mondinos`:'Free cosmetic'}</small><small>${eq?'Selected / equipped':own?'Owned':'Buyable · appearance only'}</small></div><button class="button small" data-action="cosmetic" data-id="${esc(c.id)}" aria-label="${eq?'Selected':own?'Equip':'Buy'} ${esc(c.name)}${c.cost?` for ${c.cost} Mondinos`:''}">${eq?'Selected':own?'Equip':`Buy · ${c.cost} 🌙`}</button></article>`}).join('')
 shell(`<section class="card"><div class="eyebrow">PROFILE · LIVE PREVIEW</div><div class="courier-profile"><div id="preview">${courierSvg(u)}<div class="wear" aria-hidden="true">${state.accessories.equipped.filter(id=>!['hat','crown','shades','star','bow','wings','antenna','helmet','mohawk','stardust','ringed'].includes(id)).map(id=>CONFIG.cosmetics.find(c=>c.id===id)?.emoji||'').join(' ')}</div></div><div><h1>${esc(u.name||'Visitor')}</h1><label class="field">Nickname<input id="profile-name" maxlength="24" value="${esc(u.name||'')}" autocomplete="nickname"></label><p>Space courier · outfit explorer</p><p class="player-code">PLAYER CODE<br><strong>${esc(u.code||'MQ-PENDING')}</strong></p><button class="button primary" data-action="save-look">Save / Equip look</button></div></div><h2>Free color kit</h2><p class="small">Color choices are always free and only change your courier’s appearance.</p><div class="color-row">${[['skin','Face','skin','skinTones'],['hair','Hair','hair','hairColors'],['suit','Suit','suit','suitColors']].map(([key,label,field,palette])=>`<div class="swatch-field"><label>${label}<input type="color" value="${esc(u[field]||CONFIG.look.defaults[field])}" data-color="${key}" aria-label="${label} color"></label><div class="palette" role="group" aria-label="${label} palette">${CONFIG.look[palette].map(color=>`<button type="button" class="palette-dot" style="--swatch:${color}" data-palette="${key}" data-value="${color}" aria-label="${label} ${color}" title="${color}"></button>`).join('')}</div></div>`).join('')}</div><h2>Hair & headgear</h2>${gearFor(['hairStyle'])}${gearFor(['headgear'])}<h2>Hair accessories</h2>${gearFor(['hair'])}<h2>Suit styles & capsule collection</h2>${gearFor(['suitStyle','suit','accessory','helmet'])}<h2>Profile · rank, routes & record</h2><p>Available Mondinos <b>${state.wallet} 🌙</b> · earned lifetime <b>${state.earned} 🌙</b> · rank <b>#${playerRank()}</b></p><p>Routes progress: ${new Set(state.deliveries.map(x=>x.placeId)).size} visited places · ${state.spotted.length} stickers spotted</p><h3>Recent history</h3>${state.history.slice().reverse().slice(0,6).map(h=>`<p class="small">${esc(h.label)} · ${h.amount>=0?'+':''}${h.amount} 🌙</p>`).join('')||'<p class="small">No activity recorded yet.</p>'}<h2>Inventory & lifetime distribution</h2><div class="inventory">${['flyers','posters','stickers'].map(k=>`<div><b>${state.inventory[k]}</b><span>${k} available</span><small>distributed: ${state.distributed[k]}</small></div>`).join('')}</div><p class="small">Need more? Collect at the tent. Distribution never silently takes inventory below zero.</p><h2>Space locker · one Mondino wallet</h2><p>Available balance: <b>${state.wallet} 🌙</b>. Cosmetics are visual only; once owned, gear can be equipped or unequipped for free.</p></section>`)
}

function equipCosmetic(c){if(['hairStyle','headgear','suitStyle'].includes(c.kind)){state.user[{hairStyle:'hairStyle',headgear:'headgear',suitStyle:'suitStyle'}[c.kind]]=c.value}else if(!state.accessories.equipped.includes(c.id))state.accessories.equipped.push(c.id);else state.accessories.equipped=state.accessories.equipped.filter(id=>id!==c.id)}function requestRedemption(itemId,type='reward'){if(type==='accessory'){let c=CONFIG.cosmetics.find(x=>x.id===itemId);if(!c)throw Error('Accessory not found.');if(state.accessories.owned.includes(c.id)){equipCosmetic(c);save();return {type:'accessory',itemId:c.id,status:'equipped',name:c.name,cost:0}}if(state.wallet<c.cost)throw Error('Not enough Mondinos.');state.wallet-=c.cost;state.accessories.owned.push(c.id);equipCosmetic(c);history('accessory-purchase','Purchased and equipped · '+c.name,-c.cost,{itemId:c.id});save();return {type:'accessory',itemId:c.id,status:'equipped',name:c.name,cost:c.cost}}let item=state.rewards.find(x=>x.id===itemId);if(!item||(mqAgeU16()&&Number(item.minAge)>=16))throw Error('Prize not found.');if(item.stock<=0)throw Error('Not enough stock.');if(state.wallet<item.cost)throw Error('Not enough Mondinos.');if(state.redemptionRequests.some(x=>x.playerCode===state.user?.code&&x.itemId===itemId&&isPending(x)))throw Error('You already have a pending request for this prize.');state.wallet-=item.cost;item.stock--;let req={id:uid(),type,itemId,name:item.name,cost:item.cost,category:item.category||item.kind,playerName:state.user?.name||'Courier',playerCode:state.user?.code||'NO-CODE',status:'pending',at:Date.now()};state.redemptionRequests.push(req);history('redemption-request','Request · '+item.name,-item.cost,{requestId:req.id});save();return req}function isPending(r){return r.status==='pending'||r.status==='pendiente'}function requestStatusLabel(status){return ({pending:'Pending',pendiente:'Pending',rejected:'Rejected',rechazado:'Rejected',verified:'Verified',verificado:'Verified',delivered:'Delivered',entregado:'Delivered'})[status]||String(status||'Unknown').replace(/[_-]+/g,' ').replace(/\b\w/g,c=>c.toUpperCase())}function moderatePickup(id,decision){let r=state.pickupRequests.find(x=>x.id===id&&isPending(x));if(!r)throw Error('Pending pickup not found.');if(!state.adminMode)throw Error('Enable admin mode to verify.');if(decision==='reject'){let before=mqRank();for(let k of ['flyers','posters','stickers'])state.inventory[k]=Math.max(0,state.inventory[k]-(+r.quantities[k]||0));state.wallet-=r.points;state.earned=Math.max(0,state.earned-r.points);r.status='rejected';history('pickup-rejected','Pickup rejected · points reversed',-r.points,{requestId:id,playerId:r.playerCode});r.resolvedAt=Date.now();save();return r}if(decision==='accept'){r.status='verified';r.resolvedAt=Date.now();save();return r}throw Error('Invalid decision.')}function moderateRequest(id,decision){let r=state.redemptionRequests.find(x=>x.id===id&&isPending(x));if(!r)throw Error('Pending request not found.');if(!state.adminMode)throw Error('Enable admin mode to verify.');if(decision==='reject'){state.wallet+=r.cost;if(r.type==='reward'){let item=state.rewards.find(x=>x.id===r.itemId);if(item)item.stock++}r.status='rejected';r.resolvedAt=Date.now();history('redemption-refund','Rejected prize · '+r.name,-r.cost,{requestId:id,playerCode:r.playerCode});save();return r}if(decision!=='accept')throw Error('Invalid decision.');r.status='delivered';r.resolvedAt=Date.now();history('redemption-approved','Delivery verified · '+r.name,0,{requestId:id});save();return r}function safeRewardSvg(raw){const fallback=DEFAULT_REWARD_SVGS[0];try{const src=String(raw||'').slice(0,12000),doc=new DOMParser().parseFromString(src,'image/svg+xml'),root=doc.documentElement;if(root.localName!=='svg'||doc.querySelector('parsererror'))return fallback;const allowed=new Set(['svg','g','path','rect','circle','ellipse','line','polyline','polygon']),attrs={svg:new Set(['viewBox','width','height']),g:new Set([]),path:new Set(['d','fill','stroke','stroke-width','stroke-dasharray','fill-rule','stroke-linecap','stroke-linejoin']),rect:new Set(['x','y','width','height','rx','ry','fill','stroke','stroke-width']),circle:new Set(['cx','cy','r','fill','stroke','stroke-width']),ellipse:new Set(['cx','cy','rx','ry','fill','stroke','stroke-width']),line:new Set(['x1','y1','x2','y2','stroke','stroke-width']),polyline:new Set(['points','fill','stroke','stroke-width']),polygon:new Set(['points','fill','stroke','stroke-width'])};const out=document.createElementNS('http://www.w3.org/2000/svg','svg');for(const a of ['viewBox','width','height']){let v=root.getAttribute(a);if(v&&/^[0-9., xX+-]{1,50}$/.test(v))out.setAttribute(a,v)}if(!out.hasAttribute('viewBox'))out.setAttribute('viewBox','0 0 96 72');let count=0;function copy(from,to){for(const ch of [...from.children]){if(++count>120)return;if(!allowed.has(ch.localName)||ch.namespaceURI!=='http://www.w3.org/2000/svg')continue;let el=document.createElementNS('http://www.w3.org/2000/svg',ch.localName);for(const a of [...ch.attributes]){if(!attrs[ch.localName].has(a.name)||a.name.toLowerCase().startsWith('on'))continue;let v=a.value;if(v.length>1500||/[<>"'`]|url\s*\(|javascript:/i.test(v))continue;if(['fill','stroke'].includes(a.name)&&!(/^(none|currentColor|#[0-9a-f]{3,8}|[a-z]{1,20})$/i.test(v)))continue;if(['d','points','viewBox','stroke-dasharray'].includes(a.name)&&!/^[a-zA-Z0-9., +\-]{1,1500}$/.test(v))continue;if(!/^[0-9a-zA-Z#.,% +\-]{1,1500}$/.test(v))continue;el.setAttribute(a.name,v)}to.appendChild(el);copy(ch,el)}}copy(root,out);return out.outerHTML.slice(0,3000)}catch(e){return fallback}}function shopPrizes(){let admin=state.adminMode,reqs=state.redemptionRequests;let playerReq=reqs.filter(r=>r.playerCode===state.user?.code);shell(`<section class="card">${mqHero()}${mqTabs('rewards')}<p>Available: ${state.wallet} 🌙 · Player code: <b>${esc(state.user?.code||'MQ-PENDING')}</b>. Physical items require admin verification; accessories apply immediately.</p>${mqVisibleRewards().map(r=>`<article class="cosmetic"><div class="reward-art">${safeRewardSvg(r.svg)}</div><div class="reward-copy"><b>${esc(r.name)}</b><small>${esc(r.category)} · ${r.cost} Mondinos</small><small>${esc(r.description||'')}</small><span class="reward-stock">STOCK ${r.stock}</span></div><button class="button small" data-action="redeem" data-id="${esc(r.id)}">Request · ${r.cost} 🌙</button></article>`).join('')}<h2>Accessories · instant purchase</h2>${CONFIG.cosmetics.filter(c=>c.cost>0).map(c=>`<article class="cosmetic"><span class="cosmetic-icon">${c.emoji}</span><div><b>${esc(c.name)}</b><small>Accessory · ${c.cost} Mondinos</small></div><button class="button small" data-action="cosmetic" data-id="${esc(c.id)}">Buy · ${c.cost} 🌙</button></article>`).join('')}<h2>My requests · ${esc(state.user?.code||'')}</h2>${playerReq.slice().reverse().map(r=>`<article class="announcement"><b>${esc(r.name)}</b> · ${r.cost} 🌙 · <strong>${esc(requestStatusLabel(r.status))}</strong></article>`).join('')||'<p class="small">No requests yet.</p>'}<h2>Pending requests</h2>${reqs.filter(r=>isPending(r)).map(r=>`<p>${esc(r.name)} · ${esc(requestStatusLabel(r.status))} · ${esc(r.playerCode)}</p>`).join('')||'<p class="small">None pending.</p>'}</section>${admin?`<section class="admin-console"><div class="console-head"><span>✦ MONDQUEST / VERIFICATION CONTROL</span><span><i class="console-led"></i> ONLINE</span></div><div class="console-screen"><div>CRT MONITOR · VERIFY PHYSICAL HANDOFF WITH PLAYER CODE</div><div class="console-unit"><h2>MATERIAL PICKUPS · PLAYER CODE</h2>${state.pickupRequests.filter(r=>isPending(r)).map(r=>`<article class="request-row">PICKUP · ${esc(r.playerName)} · <strong>${esc(r.playerCode)}</strong><br>✉ ${r.quantities.flyers} · 🪧 ${r.quantities.posters} · ✨ ${r.quantities.stickers}${r.pendingMaterial&&Object.values(r.pendingMaterial).some(n=>n>0)?`<p class="pending-material"><b>This player still has ${r.pendingMaterial.flyers||0} flyers / ${r.pendingMaterial.posters||0} posters / ${r.pendingMaterial.stickers||0} stickers undelivered from the previous batch</b></p>`:''}<div class="actions"><button class="button primary" data-action="pickup-accept" data-id="${esc(r.id)}">Verify handoff</button><button class="button danger" data-action="pickup-reject" data-id="${esc(r.id)}">Reject and reverse</button></div></article>`).join('')||'NO PICKUPS AWAITING VERIFICATION'}</div><div class="console-unit"><h2>PENDING REQUESTS</h2>${reqs.filter(r=>isPending(r)).map(r=>`<article class="request-row"><b>${esc(r.name)}</b> · ${r.cost} MND<br>PLAYER: ${esc(r.playerName)} · CODE: <strong>${esc(r.playerCode)}</strong><br>TYPE: ${esc(r.type)}<div class="actions"><button class="button primary" data-action="admin-accept" data-id="${esc(r.id)}">Approve / mark delivered</button><button class="button danger" data-action="admin-reject" data-id="${esc(r.id)}">Reject / refund</button></div></article>`).join('')||'NO REQUESTS IN QUEUE'}</div><div class="console-unit"><h2>EDIT CATALOG / STOCK</h2>${state.rewards.map(r=>`<form class="reward-edit" data-id="${esc(r.id)}"><label class="field">Name<input name="name" maxlength="60" required value="${esc(r.name)}"></label><label class="field">Cost<input name="cost" type="number" min="0" value="${r.cost}" required></label><label class="field">Stock<input name="stock" type="number" min="0" value="${r.stock}" required></label><label class="field">Description<input name="description" maxlength="140" value="${esc(r.description||'')}"></label><label class="field">SVG inline<input name="svg" maxlength="3000" value="${esc(r.svg||'')}"></label><button class="button primary">Save ${esc(r.name)}</button></form>`).join('')}</div></div></section>`:''}`)}
function ranking(){shell(`<section class="card"><div class="eyebrow">LOCAL RANKING</div><h1>Your record</h1><p>The local demo does not invent other players or merge devices. A community ranking needs a shared backend.</p><article class="rank-row"><b>—</b><span>${esc(state.user?.name||'Courier')}</span><strong>${state.earned} 🌙 ganados · ${esc(state.user?.code||'')}</strong></article><button class="button quiet" data-view="map">← Back to map</button></section>`)}
function pointsTable(){const rows=[['Pickup',CONFIG.points.pickup+' per batch'],['Discover a place','+'+CONFIG.points.discover],['Flyer','+'+CONFIG.points.deliverPerItem+' per flyer'],['Poster','+'+CONFIG.points.posterPerItem+' per poster'],['Sticker placed','+'+CONFIG.points.stickerPerItem+' per sticker'],['Sighting (base)',CONFIG.spotted.baseBerlin+'–'+CONFIG.spotted.max],['Sighting photo / poster / discovery','+'+CONFIG.points.spottedPhoto+' / +'+CONFIG.points.deliveryPhoto+' / +'+CONFIG.points.discoverPhoto],['Rating','+'+CONFIG.points.rating]];return `<table class="points-table"><thead><tr><th>Action</th><th>Mondinos</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r[0]}</td><td>${r[1]}</td></tr>`).join('')}</tbody></table>`}function manual(){const entries=[['Points · dynamic table',pointsTable()],['Secrets / Tips','Adding a photo to sightings, posters, or place discoveries gives +2. Adventure actions are consumed only by base actions, not combos or streaks.'],['Flyers','First delivery: 100% of CONFIG.points.deliverPerItem per flyer. Self-restock after 24 hours: 100%. Hot place (another player delivered in the past 24 hours): ×'+CONFIG.points.flyerHotMultiplier+'. Repeat delivery without restock: 0 points and does not reset the 24-hour timer. Fractional points accumulate until whole points are reached.'],['Combos, streaks and ranks','Combos: '+CONFIG.combos.map(c=>c.label+' +'+c.bonus).join(', ')+'. Regularidad: '+CONFIG.regularity.days+' different days in '+CONFIG.regularity.windowDays+' days for +'+CONFIG.regularity.bonus+'. The adventure multiplier applies to all eligible rewards; combos and streaks are also awarded without consuming adventure uses. A chest is earned for every rank crossed.'],['Pickup batches','Each pickup gives '+CONFIG.points.pickup+' points. You can request a new batch even while materials are pending. A reminder appears on day 7; if '+CONFIG.pickup.expiryDays+' days pass after pickup with no deliveries from that batch, '+CONFIG.pickup.expiryPenalty+' pickup points are reversed and remaining materials are removed, with no additional penalty.'],['Delivery confirmation','Enter non-negative whole numbers (0–999) for flyers, posters and stickers; at least one must be greater than zero. A delivery cannot exceed local inventory. Confirmation is guarded against repeat submission and uses an action ID; only valid actions update the balance. Flyer repeat/restock rules can result in zero flyer points.'],['Inventory and history','Deliveries consume materials. Declines and reversals are recorded as negative history entries; awarded chests are not revoked. Stored locally in this browser.'],['Places, ratings and reports','Ratings and reports are identified by player ID, not the visible name.']];shell(`<section class="card"><button class="button quiet small" data-view="map">← Map</button><div class="eyebrow">FIELD MANUAL</div><h1>Flight rules</h1>${entries.map(([t,b])=>`<details class="manual-item"><summary>${t}</summary><div>${b}</div></details>`).join('')}</section>`)}
function newsReadKey(){return `mq-news-read-${String(state.user?.code||state.user?.id||'guest')}`}function unreadNews(){let seen=[];try{seen=JSON.parse(localStorage.getItem(newsReadKey())||'[]')}catch(e){}let ids=new Set(seen);return allNews().filter(a=>!ids.has(String(a.id))).length}function markNewsRead(){try{localStorage.setItem(newsReadKey(),JSON.stringify(allNews().map(a=>String(a.id))))}catch(e){}}function announcements(){let list=allNews();markNewsRead();shell(`<section class="card"><div class="eyebrow">FROM THE CIRCUS</div><h1>News & announcements</h1>${newsPanel()}${list.map(a=>`<article class="announcement"><small>${esc(a.type||'news')}</small><h2>${esc(a.title)}</h2><p>${esc(a.body||a.text||'')}</p></article>`).join('')||'<p>No announcements right now.</p>'}</section>`)}
function more(){shell(`<section class="card"><div class="eyebrow">ROUTE CONTROL DECK</div><h1>More</h1><p class="small">A quiet control deck for the rest of your route.</p><div class="more-grid"><button class="button" data-view="missions">⭐ Missions</button><button class="button" data-view="places">📍 Places & routes</button><button class="button" data-view="pickup">📦 Pickup</button><button class="button" data-view="shop">🚚 Cargo</button><button class="button" data-view="adventures">🪐 Adventures</button><button class="button" data-view="ranking">🏆 Ranking</button><button class="button" data-view="players">👤 Players online</button><button class="button" data-view="chat">💬 Moon chat</button><button class="button" data-view="wardrobe">👕 Wardrobe</button><button class="button" data-view="spotted">🔭 Sightings</button><button class="button" data-view="courier">👤 Profile</button><button class="button" data-view="announcements">📣 News</button><button class="button" data-view="manual">📖 Manual</button><button class="button" data-view="settings">⚙️ Settings</button><button class="button" data-view="map">🌙 Return to map</button></div><div class="admin-console"><div class="console-head"><span>LOCAL CONTROL DECK · ADMIN DEMO LOCAL</span><i class="console-led"></i></div><label class="check-field"><input type="checkbox" id="admin-toggle" ${state.adminMode?'checked':''}> ADMIN DEMO LOCAL · NOT AUTHENTICATED</label><p class="small"><b>ADMIN DEMO LOCAL — not authenticated.</b> This visual demo toggle grants no secure privileges. Anyone using this browser can enable it. Posts are stored only in this browser.</p>${state.adminMode?`<div class="console-screen"><div class="console-unit"><h2>PLACE REPORTS · REVIEW QUEUE</h2>${state.placeFlags.filter(f=>f.status==='pending').map(f=>`<article class="request-row"><b>${esc(f.placeName||state.places.find(p=>p.id===f.placeId)?.name||'Place')}</b> · ${esc(f.reason)}<br>REPORTER: ${esc(f.reporterName||f.reporter)} · ${new Date(f.timestamp).toLocaleString("en-US")} · reward ${f.rewarded?'paid':'not paid'}<div class="actions"><button class="button primary" data-action="place-flag-confirm" data-id="${esc(f.id)}">Confirm · retire place</button><button class="button danger" data-action="place-flag-reject" data-id="${esc(f.id)}">Reject · re-enable place</button></div></article>`).join('')||'NO PLACE REPORTS AWAITING REVIEW'}</div><div class="console-head">ADMIN MESSAGES · LOCAL DEMO ONLY <i class="console-led"></i></div><form id="announce-form"><input type="hidden" name="newsId"><label class="field">Title<input name="title" required maxlength="100"></label><label class="field">Text<textarea name="body" required maxlength="1200" rows="5"></textarea></label><label class="field">Optional image URL or thumbnail data<input name="image" maxlength="300000" placeholder="Optional"></label><label class="field">Upload a small image thumbnail<input type="file" id="news-image-upload" accept="image/*" aria-label="Upload a small news image"></label><div class="emoji-tools"><span>Insert emoji:</span>${['🌙','🎪','✨','📣','💚','⭐','🎟️','🎉','📍','🪐','☕','🧡'].map(e=>`<button type="button" class="emoji-button" data-action="insert-emoji" data-emoji="${e}" aria-label="Insert ${e}">${e}</button>`).join('')}</div><label class="field">Place type<select name="type">${NEWS_TYPES.map(t=>`<option>${t}</option>`).join('')}</select></label><div class="actions"><button class="button primary" id="news-submit">Post message</button><button class="button quiet" type="button" data-action="cancel-news-edit">Clear</button></div></form>${allNews().map(a=>`<article class="announcement"><b>${esc(a.title)}</b> · ${esc(a.type||'news')}<div class="actions"><button class="button small" data-action="edit-announcement" data-id="${a.id}">Edit</button><button class="button small danger" data-action="delete-announcement" data-id="${a.id}">Delete</button></div></article>`).join('')}`:''}</div><button class="button danger" data-action="reset">Reset demo data</button><p class="small">Demo storage: localStorage on this device. Not secure, not multiuser.</p></section>`)}
function flagPlace(placeId,reason){let p=state.places.find(x=>x.id===placeId);if(!p||p.retired){toast('This place is no longer available.');return {ok:false,warning:true}}if(state.placeFlags.some(f=>f.placeId===placeId&&f.status==='pending')||p.flagged){toast('This place is already flagged and awaiting admin review.');return {ok:false,warning:true}}if(!state.user){toast('Choose a courier profile before reporting a place.');return {ok:false,warning:true}}if(!['No flyers allowed here',"Place doesn't exist"].includes(reason)){toast('Choose a valid report reason.');return {ok:false,warning:true}}let reporter=state.user.id||state.user.code,previous=state.placeFlags.some(f=>f.placeId===placeId&&f.reporter===reporter&&f.rewarded),rec={id:uid(),placeId,placeName:p.name,reporter,reporterName:state.user.name,reason,timestamp:Date.now(),rewarded:!previous,status:'pending'};state.placeFlags.push(rec);p.flagged=true;p.flagId=rec.id;if(rec.rewarded){history('place-report','Reported place · '+p.name,CONFIG.points.rating,{placeId,flagId:rec.id,reporter});award(CONFIG.points.rating)}else save();refreshMarkers();toast(rec.rewarded?'Report sent for admin review.':'Report sent for admin review. You have already received the reporting reward for this place.');return {ok:true,record:rec,points:rec.rewarded?1:0}}function moderatePlaceFlag(id,decision){let f=state.placeFlags.find(x=>x.id===id&&x.status==='pending');if(!f)throw Error('Pending place report not found.');if(!state.adminMode)throw Error('Enable admin mode to review place reports.');let p=state.places.find(x=>x.id===f.placeId);if(decision==='confirm'){f.status='confirmed';f.resolvedAt=Date.now();if(p){p.flagged=false;p.retired=true;p.retiredAt=f.resolvedAt}}else if(decision==='reject'){f.status='rejected';f.resolvedAt=Date.now();if(p){p.flagged=false;delete p.flagId}}else throw Error('Invalid decision.');save();refreshMarkers();return f}function award(n,opts={}){n=Math.max(0,Number(n)||0);mqInit();let r0=mqRank(),extra=0;if(n>0&&state.adventure){extra=Math.floor(n*(mqMult()-1));if(opts.consumeAdventure!==false)state.adventure.left--}let total=n+extra;state.wallet+=total;state.earned+=total;if(extra)history('bonus','Adventure bonus x'+mqMult(),extra);if(state.adventure&&state.adventure.left<=0)mqFinishAdv();let r1=mqRank();if(r1>r0){state.chests=(state.chests||0)+(r1-r0);setTimeout(()=>toast('Rank up! '+MQ_RANKS[mqRank()][0]+' · '+(r1-r0)+' Magic chest(s).'),50)}if(n>0&&!opts.noBonuses)mqBonuses();save();return total}function history(type,label,amount=0,extra={}){state.history.push({id:uid(),type,label,amount,at:Date.now(),playerCode:String(state.user?.code||state.user?.id||''),avatarSnapshot:playerSnapshot(),...extra})}function scoreFlyerDrop(place,qty,userCode,now=Date.now(),confirmOther=true,restock=false){let drops=state.deliveries.filter(d=>d.placeId===place.id&&(+d.flyers||0)>0&&!d.noPointRepeat).sort((a,b)=>b.at-a.at),last=place.lastDropAt?{at:place.lastDropAt,dropper:place.dropper}:null;if(!last&&drops.length){let d=drops[0];last={at:d.at,dropper:d.playerCode||d.userId||''}}let id=String(userCode||state.user?.id||state.user?.code||''),ownPrevious=drops.find(d=>String(d.playerCode||d.userId||'')===id),ownAge=ownPrevious?now-ownPrevious.at:Infinity,ownLast=!!last&&String(last.dropper||'')===id,elapsed=last?now-last.at:Infinity;if(ownPrevious){if(restock&&ownAge>=86400000&&elapsed>=86400000)return{points:qty*CONFIG.points.deliverPerItem,notice:'',first:false,restock:true};return{points:0,notice:'Restock earns points only after 24 hours without any flyer delivery here.',repeat:true}}if(last&&elapsed<86400000&&!ownLast)return{points:qty*CONFIG.points.deliverPerItem*CONFIG.points.flyerHotMultiplier,notice:'',reduced:true,first:false};if(ownLast){return{points:0,notice:'You already left flyers here; no points until a restock after 24 hours',repeat:true}}return{points:qty*CONFIG.points.deliverPerItem,notice:'',first:!last}}function processLog(form){let kind=form.dataset.kind,id=form.dataset.place,p=state.places.find(x=>x.id===id),fd=new FormData(form),submitId=String(fd.get('submitId')||'');if(kind==='drop'&&fd.get('flyerMode')==='restock')kind='restock';if(submitId&&state.history.some(x=>x.submitId===submitId)){toast('This action was already saved.');return}let values={flyers:0,posters:0,stickers:0};for(let k of Object.keys(values)){if(fd.has(k)){let val=Number(fd.get(k));if(!Number.isInteger(val)||val<=0){toast('Enter a whole quantity greater than zero.');return}values[k]=val}}if(kind==='missing'){if(!p)return;history('field-note','Added a field note at '+p.name,0,{placeId:id,submitId});p.missingAt=Date.now();p.lastUpdated=Date.now();save();toast('Field note saved.');openLocationDetail(id);return}let mat=kind==='poster'?'posters':kind==='stickers'?'stickers':'flyers';if(!p)return;if(p.flagged||p.retired){toast('This place is temporarily unavailable.');return}let qty=values[mat];if(!qty){toast('Enter a positive quantity.');return}if(state.inventory[mat]<qty){toast(`Only ${state.inventory[mat]} ${mat} available. Collect more at the material tent.`);return}let photo=fd.get('photo')?.size>0,points,anti={};if(mat==='flyers'){let verdict=scoreFlyerDrop(p,qty,state.user?.id||state.user?.code,Date.now(),true,kind==='restock');points=verdict.points;anti=verdict;if(verdict.repeat)toast(verdict.notice)}else points=qty*(mat==='stickers'?CONFIG.points.stickerPerItem:mat==='posters'?CONFIG.points.posterPerItem:CONFIG.points.deliverPerItem);if(photo&&mat==='posters')points+=CONFIG.points.deliveryPhoto;points=mqCarry(points);state.inventory[mat]-=qty;state.distributed[mat]+=qty;let leftQty=qty;for(const batch of (state.batches||[])){if(batch.expired||leftQty<=0)continue;let available=Math.max(0,(batch.taken[mat]||0)-(batch.delivered?.[mat]||0)),take=Math.min(leftQty,available);batch.delivered=batch.delivered||{};batch.delivered[mat]=(batch.delivered[mat]||0)+take;leftQty-=take;}let code=String(state.user.code||state.user.id||'');state.players=state.players||{};state.players[code]=playerSnapshot();let log={id:uid(),placeId:id,placeName:p.name,user:state.user.name,userId:code,playerCode:code,avatarSnapshot:playerSnapshot(),kind,...values,photo,points,noPointRepeat:!!(mat==='flyers'&&anti.repeat),at:Date.now(),note:String(fd.get('note')||'').slice(0,160),submitId};state.deliveries.push(log);if(mat==='flyers'&&anti.points>0){p.lastDropAt=log.at;p.dropper=code}if(!(mat==='flyers'&&anti.repeat))p.lastUpdated=log.at;history('distribution',`${kind==='restock'?'Restock':kind==='poster'?'Poster placed':kind==='stickers'?'Stickers placed':'Flyers dropped'} · ${p.name}`,points,{placeId:id,submitId,quantities:values,playerCode:log.playerCode});award(points);save();if(!anti.notice)toast(`Saved now · +${points} Mondinos${points?'':' · leftovers carry over'}`);openLocationDetail(id)}
function saveNewPlace(form){let fd=new FormData(form),name=String(fd.get('name')||'').trim(),addressParts=readAddress(fd);if(!validPlaceFields(name,addressParts,fd)){toast('Complete name, type, street + number, city, country, drop spot, notes and poster size.');return}let address=[addressParts.street,addressParts.city,addressParts.country].filter(Boolean).join(', '),now=Date.now(),isEdit=!!form.dataset.edit,p;if(isEdit){p=state.places.find(x=>x.id===form.dataset.edit);if(!p)return;Object.assign(p,{name,address,addressParts,type:fd.get('type'),spot:fd.get('spot'),notes:fd.get('notes'),posterSize:fd.get('posterSize'),lat:mapDraft.lat,lng:mapDraft.lng,lastUpdated:now});history('place-edit','Edited place · '+name)}else{p={id:uid(),name,address,addressParts,type:fd.get('type'),spot:fd.get('spot'),notes:fd.get('notes'),posterSize:fd.get('posterSize'),photo:fd.get('photo')?.size>0,discoverer:state.user.name,discovererCode:String(state.user.code||state.user.id||''),discovererSnapshot:playerSnapshot(),createdAt:now,lastUpdated:now,status:'needs',lat:mapDraft.lat,lng:mapDraft.lng,ratings:{}};state.places.push(p);let awardN=CONFIG.points.discover+(p.photo?CONFIG.points.discoverPhoto:0);history('discover','Discovered place · '+name,awardN,{placeId:p.id});award(awardN)}save();toast(isEdit?'Place details saved.':`New place added · +${CONFIG.points.discover} Mondinos`);placeDetail(p.id)}
function handleAction(action,b){let id=b.dataset.id;switch(action){case'signup':{let el=document.getElementById('new-name'),name=(el?.value||'').trim(),age='';if(!name){toast('Pick a nickname first.');return}registerPlayer(name,age);go('guide');break}case'finish-guide':case'skip-guide':state.guideDone=true;save();go('menu');break;case'mission':if(b.dataset.kind==='spotted')go('spotted');else if(b.dataset.kind==='discover')go('discover');else{let place=state.places.find(x=>x.id===id);if(!place){queuedMission=b.dataset.kind||'';go('places');toast('Choose a place to log this action.');return}openLocationDetail(id,b.dataset.kind||'')}break;case'new-place':go('discover');break;case'world-view':if(leafletInstance)leafletInstance.fitWorld();break;case'retry-map':if(leafletInstance){leafletInstance.remove();leafletInstance=null}initLeaflet();break;case'center-map':if(leafletInstance)leafletInstance.setView([52.5030,13.4557],11);break;case'search-place':{let q=prompt('Search places');if(q){let p=activePlaces().find(x=>x.name.toLowerCase().includes(q.toLowerCase()));if(p)selectPlaceOnMap(p.id);else toast('Place not found. Browse the full list in Places.')}break;}case'berlin-view':if(leafletInstance)leafletInstance.setView([52.5030,13.4557],12);break;case'toggle-places':showPlaceMarkers=!showPlaceMarkers;refreshMarkers();break;case'toggle-spotted':showSpottedMarkers=!showSpottedMarkers;refreshMarkers();break;case'geocode-place':geocodeFormAddress();break;case'geocode-spotted':geocodeSpotted();break;case'profile-save':saveProfileName();break;case'spotted':go('spotted');break;case'location-on':shareLocation();break;case'location-off':stopLocationShare();break;case'news-prev':newsMove(-1);break;case'news-next':newsMove(1);break;case'news-dot':newsIndex=Number(b.dataset.index)||0;menu();break;case'insert-emoji':{let f=document.querySelector('#announce-form textarea[name=body]'),e=b.dataset.emoji||'';if(f){let a=f.selectionStart??f.value.length,z=f.selectionEnd??a;f.value=f.value.slice(0,a)+e+f.value.slice(z);f.focus();f.setSelectionRange(a+e.length,a+e.length)}break;}case'edit-announcement':editNewsPage(id);break;case'delete-announcement':deleteNewsPage(id);break;case'cancel-news-edit':more();break;case'open-place':selectPlaceOnMap(id);openLocationDetail(id,b.dataset.kind||'');break;case'popup-log-action':openLocationDetail(id,'drop');break;case'place-report':flagPlace(id,b.dataset.reason||'');placeDetail(id);break;case'place-flag-confirm':case'place-flag-reject':try{moderatePlaceFlag(id,action==='place-flag-confirm'?'confirm':'reject');toast(action==='place-flag-confirm'?'Place retired and report confirmed.':'Report rejected · place re-enabled.');more()}catch(e){toast(e.message)}break;case'edit-place':editPlace(id);break;case'rate':{let p=state.places.find(x=>x.id===id);if(!p)return;p.ratings=p.ratings||{};if(p.ratings[state.user.id||state.user.code]){toast('One rating per profile in this demo.');return}p.ratings[state.user.id||state.user.code]=+b.dataset.score;award(CONFIG.points.rating);history('rating','Rated '+p.name,CONFIG.points.rating,{placeId:id});save();toast('Rating saved.');placeDetail(id);break}case'cargo-tab':cargoTab=id;cargoSel=null;shop();break;case'cargo-sel':cargoSel=id;cargoScreen();break;case'craft':try{mqCraft(id)}catch(e){toast(e.message)}break;case'g-equip':{mqInit();let a=state.gadgets.equipped,i=a.indexOf(id);if(i>=0)a.splice(i,1);else{if(a.length>=3)a.shift();a.push(id)}save();cargoScreen();break}case'chest-open':try{mqOpenChest()}catch(e){toast(e.message)}break;case'adv-start':try{mqStartAdv(id)}catch(e){toast(e.message)}break;case'adv-stop':state.adventure=null;save();go('adventures');break;case'cosmetic':try{const _sc=document.querySelector('.view')?.scrollTop||0,_c=CONFIG.cosmetics.find(x=>x.id===id);if(_c&&!_c.cost&&['hairStyle','headgear','suitStyle'].includes(_c.kind)){if(!state.accessories.owned.includes(id))state.accessories.owned.push(id);equipCosmetic(_c);save();toast('Look updated.');courier();const _v=document.querySelector('.view');if(_v)_v.scrollTop=_sc;break}mqGate(id);let r=requestRedemption(id,'accessory');toast(r.status==='equipped'?'Accessory purchased and equipped.':'Accessory equipped.');b.dataset.from==='cargo'?cargoScreen():courier();{const _v=document.querySelector('.view');if(_v)_v.scrollTop=_sc}}catch(e){toast(e.message)}break;case'save-look':Object.assign(state.user,courierDraft);saveProfileName();save();toast('Profile saved.');courier();break;case'redeem':try{requestRedemption(id,'reward');toast('Purchase submitted for verification · Mondinos reserved.');shop()}catch(e){toast(e.message)}break;case'pickup-accept':case'pickup-reject':try{let r=moderatePickup(id,action==='pickup-accept'?'accept':'reject');toast(r.status==='verified'?'Pickup verified.':'Pickup rejected and reversed.');shop()}catch(e){toast(e.message)}break;case'admin-accept':case'admin-reject':try{let r=moderateRequest(id,action==='admin-accept'?'accept':'reject');toast(r.status==='delivered'?'Delivery verified.':'Request rejected · Mondinos and stock returned.');shop()}catch(e){toast(e.message)}break;case'reset':if(confirm('Reset all MondQuest demo data on this device? This cannot be undone.')){localStorage.removeItem(CONFIG.storageKey);location.reload()}break;}}

