+(has('mohawk')?`<path d="M38 40l4-14 4 12 4-16 4 16 4-12 4 14z" fill="${suit}" ${st} stroke-width="2.5"/>`:'')
+(has('star')?`<path d="M50 24l3 7 7 1-5 5 1 7-6-4-6 4 1-7-5-5 7-1z" fill="#FFD21F" ${st} stroke-width="2"/>`:'')
+(has('bow')?`<path d="M64 30l14-6v14zM64 30 50 24v14z" fill="#FF5FB0" ${st} stroke-width="2.5"/><circle cx="64" cy="30" r="3.5" fill="#FFD21F" ${st} stroke-width="2"/>`:'')
+(has('crown')?`<path d="M32 42 36 20l10 10 4-16 4 16 10-10 4 22z" fill="#FFD21F" ${st} stroke-width="3"/>`:'')
