function syncAtlasFilterControls(){const entries=[['toggle-places',showPlaceMarkers,'place-filter-state','Distribution places'],['toggle-spotted',showSpottedMarkers,'spotted-filter-state','Sticker sightings']];for(const [action,enabled,labelId,label] of entries){const button=document.querySelector(`[data-action="${action}"]`);if(!button)continue;const value=button.querySelector(`#${labelId}`);if(value)value.textContent=enabled?'on':'off';button.classList.toggle('active',enabled);button.setAttribute('aria-pressed',String(enabled));button.title=`${label}: ${enabled?'shown':'hidden'}`}}
