function renderOfflineMap(el){let places=!showPlaceMarkers?[]:activePlaces().filter(hasMapCoords),south=52.48,north=52.55,west=13.40,east=13.48;const placePins=places.map(p=>{let left=Math.max(5,Math.min(95,(+p.lng-west)/(east-west)*100)),top=Math.max(12,Math.min(85,(north- +p.lat)/(north-south)*100));return `<button class="offline-map-pin" style="left:${left}%;top:${top}%" data-action="open-place" data-kind="drop" data-id="${esc(p.id)}" title="${esc(p.name)}">${typeMeta(p.type)[1]}</button>`}).join('');const spottedPins=currentView==='atlas'&&showSpottedMarkers?state.spotted.filter(x=>Number.isFinite(+x.lat)&&Number.isFinite(+x.lng)&&+x.lat>=south&&+x.lat<=north&&+x.lng>=west&&+x.lng<=east).map(x=>{let left=Math.max(5,Math.min(95,(+x.lng-west)/(east-west)*100)),top=Math.max(12,Math.min(85,(north- +x.lat)/(north-south)*100));return `<span class="offline-map-pin offline-sticker-pin" style="left:${left}%;top:${top}%" title="Sticker sighting" aria-label="Sticker sighting">🔭</span>`}).join(''):'';el.innerHTML=`<div class="offline-map">${placePins}${spottedPins}</div>`}function initLeaflet(){let el=document.getElementById('leaflet-map');if(!el)return;if(!window.L){let fallback=document.getElementById('map-fallback');if(fallback)fallback.hidden=false;renderOfflineMap(el);return}if(leafletInstance){leafletInstance.remove();leafletInstance=null}el.replaceChildren();let worldMap=!!el.closest('.card')||currentView==='atlas',selectedPlace=state.places.find(p=>p.id===activePlaceId&&hasMapCoords(p)),center=selectedPlace?[+selectedPlace.lat,+selectedPlace.lng]:[52.5030,13.4557];leafletInstance=L.map(el,{worldCopyJump:true,minZoom:(currentView==='spotted'||worldMap)?2:9,maxZoom:19,maxBounds:(currentView==='spotted'||worldMap)?[[-85,-180],[85,180]]:[[52.30,13.00],[52.72,13.75]],maxBoundsViscosity:.8}).setView((currentView==='spotted'||worldMap)?[15,0]:center,(currentView==='spotted'||worldMap)?2:selectedPlace?14:11);let chain=mqTileChain(),idx=0,tileLoaded=false,tileErrs=0,tiles=null;
let warned=false;const showTileWarning=msg=>{if(tileLoaded||warned)return;warned=true;let w=document.getElementById('map-fallback');if(w){w.hidden=false;let p=w.querySelector('p');if(p)p.textContent=msg}let cur=document.getElementById('leaflet-map');if(cur)renderOfflineMap(cur)};
const useTiles=i=>{if(tiles)leafletInstance.removeLayer(tiles);let c=chain[i];tiles=L.tileLayer(c.url,{attribution:c.attribution,maxZoom:c.maxZoom||19,subdomains:c.subdomains==null?'abc':c.subdomains});tiles.on('tileload',()=>{tileLoaded=true;tileErrs=0;let w=document.getElementById('map-fallback');if(w)w.hidden=true});tiles.on('tileerror',()=>{if(tileLoaded)return;tileErrs++;if(tileErrs>=4){tileErrs=0;if(idx<chain.length-1){idx++;useTiles(idx)}else showTileWarning('Map tiles could not be loaded from '+c.name+'. Check your connection or ad blocker, then tap Retry.')}});tiles.addTo(leafletInstance)};
useTiles(0);setTimeout(()=>{if(!tileLoaded&&document.getElementById('leaflet-map'))showTileWarning('The map is taking too long to load. Check your connection or ad blocker, then tap Retry.')},10000);refreshMarkers();if(currentView==='discover'||currentView==='editPlace'){leafletInstance.on('click',e=>{mapDraft={lat:e.latlng.lat,lng:e.latlng.lng};drawDraftMarker(mapDraft)})}if(currentView==='spotted'){leafletInstance.on('click',e=>{let f=document.getElementById('spotted-form');if(!f)return;f.elements.lat.value=e.latlng.lat;f.elements.lng.value=e.latlng.lng;mapDraft={lat:e.latlng.lat,lng:e.latlng.lng};drawDraftMarker(mapDraft);document.getElementById('coordinate-note').textContent=`Map marker · approximate coordinates ${e.latlng.lat.toFixed(4)}, ${e.latlng.lng.toFixed(4)}.`;updateSpottedPreview()})}setTimeout(()=>leafletInstance&&leafletInstance.invalidateSize(),60)}
let leafletLoad=document.createElement('script');leafletLoad.src='vendor/leaflet/leaflet.js';leafletLoad.onload=()=>{if(document.getElementById('leaflet-map'))initLeaflet()};leafletLoad.onerror=()=>{let f=document.getElementById('map-fallback');if(f)f.hidden=false;let el=document.getElementById('leaflet-map');if(el)renderOfflineMap(el)};setTimeout(()=>{if(!window.L&&document.getElementById('leaflet-map')){let f=document.getElementById('map-fallback');if(f)f.hidden=false;let el=document.getElementById('leaflet-map');if(el)renderOfflineMap(el)}},7000);document.head.appendChild(leafletLoad);
window.addEventListener('storage',e=>{if(e.key==='mq-presence'||e.key?.startsWith(PRESENCE_PREFIX)){refreshPresenceList();refreshMarkers()}if(e.key===CONFIG.storageKey&&e.newValue){try{let incoming=JSON.parse(e.newValue);if(incoming?.__updatedAt>(state.__updatedAt||0)){state=incoming;if(currentView==='map')go('menu')}}catch(err){}}});window.addEventListener('resize',()=>{if(leafletInstance)leafletInstance.invalidateSize()});setInterval(()=>{for(let i=localStorage.length-1;i>=0;i--){let k=localStorage.key(i);if(k&&k.startsWith(PRESENCE_PREFIX)){try{let x=JSON.parse(localStorage.getItem(k)||'null');if(!x||x.expires<=Date.now())localStorage.removeItem(k)}catch(e){localStorage.removeItem(k)}}}let raw=localStorage.getItem('mq-presence');if(raw){try{let legacy=JSON.parse(raw);if(Array.isArray(legacy)){let filtered=legacy.filter(x=>x&&x.expires>Date.now());if(filtered.length!==legacy.length)localStorage.setItem('mq-presence',JSON.stringify(filtered))}}catch(e){localStorage.removeItem('mq-presence')}}mqExpire();refreshPresenceList();if(leafletInstance&&currentView==='map')refreshMarkers()},60000);

