function mqTileChain(){const c=(window.MQ_CONFIG&&window.MQ_CONFIG.tiles)||{},chain=[];if(c.url)chain.push({name:c.name||'custom tiles',url:c.url,attribution:c.attribution||'',maxZoom:c.maxZoom||19,subdomains:c.subdomains==null?'abc':c.subdomains});chain.push({name:'OpenStreetMap',url:'https://tile.openstreetmap.org/{z}/{x}/{y}.png',attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',maxZoom:19,subdomains:''});return chain}
